enum DemoRulebookFixture {
    static let rulebook = #"""
{"rulebook":{"schemaVersion":"GOAT_ARENA_RULEBOOK_V1","revision":"FINAL_LOGIC_V1_4","generatedAt":"@T+0s@","source":"SERVER_ACTIVE_POLICY","divisions":{"sub":{"division":"SUB","title":"Unranked 경기 규정","eyebrow":"UNRANKED RULEBOOK","intro":"Unranked는 학습권 패키지의 정기권 학습 가능 일수와 페이백 점수를 관리하며, 같은 티어의 상위 순위 또는 바로 위 티어를 상대로 Arena 상태를 쟁탈하는 경쟁 구간입니다.","summary":["두 사용자는 Unranked 전용 U1~U9 조합의 같은 주관식 5문항을 문항당 최대 10분 동안 풉니다. U1은 기초 일반에서 시작하고 U8부터 준킬러를 섞되 킬러는 사용하지 않습니다.","이전 문항으로 돌아갈 수 없고, 5번 문항 완료 또는 시간 종료 뒤 문제는 닫힙니다. 새로고침·일시적 연결 끊김에도 제한시간은 계속 흐르며 같은 문항이 다시 표시됩니다.","문제가 닫힌 뒤 60초 안에 풀이 증거 사진 1~5장을 제출합니다. 이 필수 증거를 기한 안에 내지 않으면 별도 소명 기한 없이 자동 패배합니다.","매치가 성립한 뒤에는 상대의 서비스 닉네임만 표시하며 실명은 공개하지 않습니다.","승패는 점수 → 정답 수 → 정답 문항 풀이시간 → 전체 풀이시간 순으로 정합니다.","완전히 동점이면 방어자가 승리합니다.","1대1 경기 결과로 배치고사에서 정한 실력 기준은 바뀌지 않습니다. 공격자가 이기면 티어·티어 내 순위·GP가 함께 교환됩니다."],"rules":[{"number":1,"title":"참가 자격과 경기 종류","sections":[{"title":"이용 자격","body":["학습권 패키지가 활성 상태이고 배치고사를 완료해야 합니다.","사용 가능한 정기권 학습 가능 일수가 0일이 되더라도 마지막 공식 공격 제출 마감 전까지는 Unranked 공식 경기를 허용하며, 마감 뒤 공격·방어·복수전과 신규 매칭이 모두 중단됩니다.","학습권 만료 뒤 29일 학습권 패키지를 다시 구매하면 이전 배치를 재사용하지 않고 배치고사를 다시 완료해야 합니다."]},{"title":"배치고사 확인 방식","body":["배치고사는 문항별 서버 풀이시간과 답안 흐름을 기록하고, 결과 확인이 더 필요하면 준킬러 2문항과 킬러 2문항의 추가 확인 문제를 제공합니다.","추가 확인은 시작 위치를 더 정확하게 정하기 위한 절차이며, Arena 1대1 경기의 60초 필수 풀이 증거나 부정행위 제재 절차를 배치고사에 적용하지 않습니다."]},{"title":"공식 경기","body":["Unranked의 공식 1대1은 일반 쟁탈전과 복수전뿐입니다.","별도의 일반전은 존재하지 않습니다."]}]},{"number":2,"title":"도전 대상과 자동 매칭","sections":[{"title":"상위 순위 우선","body":["모든 티어에서 서버가 먼저 공격자와 같은 티어이면서 공격자보다 티어 내부 순위가 높은 적격 사용자를 찾습니다.","같은 티어의 상위 후보가 한 명이라도 있으면 바로 위 티어 후보로 넘어가지 않습니다.","후보군에서는 최근 72시간 일반 쟁탈전 방어 횟수가 가장 적은 사용자를 먼저 모으고, 동률이면 마지막 방어 배정이 가장 오래된 사용자를 우선합니다. 그 시각까지 같을 때만 무작위로 한 명을 정합니다.","복수전은 72시간 방어 횟수와 마지막 방어 배정 집계에서 제외하며, 상대의 닉네임이나 특정 계정은 직접 고를 수 없습니다."]},{"title":"한 티어 상향 폴백","body":["같은 티어의 상위 적격 후보가 없을 때만 정확히 바로 위 티어에서 상대를 다시 찾습니다.","두 단계 이상 위 티어로는 확장하지 않습니다. 챌린저는 위 티어가 없으므로 같은 챌린저 중 자신보다 높은 순위의 후보만 만날 수 있습니다.","각 티어의 0 GP 최하위도 공격으로 순위를 높일 수 있으며, 자신보다 아래 순위가 생기기 전까지 같은 티어 자동 방어 후보가 되지 않는 점은 별도 예외 없이 동일하게 적용합니다."]},{"title":"자동 방어 미응시","body":["자동 배정된 방어전을 시작하지 않은 기록이 5회 누적되면 자동 방어 후보에서 제외됩니다.","이 상태에서도 정기권 학습 가능 일수는 매일 기존 규정대로 차감됩니다.","참가 가능한 공격을 한 번 정상적으로 신청하면 미응시 누적이 0회로 초기화되고 자동 방어 배정이 다시 활성화됩니다."]},{"title":"시작 기한","body":["공식 매치가 만들어진 뒤 양측은 24시간 안에 시작해야 합니다.","다만 일요일을 통과하면 시작 마감은 일요일 14:00으로 앞당겨집니다.","공격자만 시작하지 않으면 방어자 승리, 방어자만 시작하지 않으면 공격자 승리로 자동 정산합니다. 양측 모두 시작하지 않으면 승패 없이 취소하며 예치한 페이백 점수는 그대로 반환합니다."]}]},{"number":3,"title":"일반 쟁탈전 페이백 점수","sections":[{"title":"경기 생성","body":["도전자는 페이백 점수 1점을 예치합니다.","방어자는 경기 생성 시 어떤 점수도 예치하지 않으며, Unranked 경기로 정기권 학습 가능 일수는 바뀌지 않습니다."]},{"title":"도전자 승리","body":["시작 티어와 관계없이 도전자가 이기면 예치한 페이백 점수 1점을 전부 반환합니다.","티어·티어 내 순위·GP는 교환되며 페이백 점수의 순변화는 없습니다."]},{"title":"방어자 승리","body":["방어자의 현재 Arena 상태를 유지하고 도전자가 예치한 페이백 점수 1점을 가져옵니다."]},{"title":"0점과 패키지 만료","body":["페이백 점수가 0점이면 일반 공격과 복수전 신청만 중단되며, 활성 29일 패키지의 남은 기능과 방어 자격은 유지됩니다.","정기권 학습 가능 일수가 0일이 되더라도 마지막 공식 공격 제출 마감 전까지는 해당 공격을 허용하며, 마감 뒤 GOAT Arena 전체가 잠기고 방어 후보에서도 제외됩니다."]}]},{"number":4,"title":"복수전","sections":[{"title":"신청","body":["가장 최근 원경기의 패자에게 결과 화면에서 한 번만 복수전 선택권을 줍니다.","복수하기를 누르면 페이백 점수 2점을 예치하고 상대는 선택권 없이 자동 참가합니다.","경기 종료를 누르면 해당 원경기의 복수전 권리는 즉시 사라집니다."]},{"title":"정상 완료","body":["복수전 신청자가 이기면 Arena 상태를 다시 교환하고 예치한 2점 중 1점을 반환하며, 나머지 1점은 수수료로 소각합니다.","복수전 신청자가 지면 Arena 상태를 유지하고 예치한 2점 중 1점은 방어자에게 이전하며, 나머지 1점은 수수료로 소각합니다."]},{"title":"24시간 미완료","body":["방어자만 미완료면 Arena 상태를 교환하고 도전자에게 1점을 반환하며 1점을 소각합니다.","도전자만 미완료면 Arena 상태를 유지하고 방어자에게 1점을 이전하며 1점을 소각합니다.","양측 모두 미완료면 Arena 상태를 유지하고 예치한 2점을 전부 소각합니다.","복수전은 최근 7일 재대결 제한의 예외이며, 양측 모두 신청 뒤 24시간 안에 완료해야 합니다."]}]},{"number":5,"title":"일요일 운영과 페이백","sections":[{"title":"일요일 경기 마감","body":["매주 일요일 14:00부터 신규 신청·수락·준비·시작을 차단합니다.","14:00 전에 시작한 경기는 문항당 10분 규칙을 적용한 채 15:00까지 답안·풀이 증거 제출과 정산을 끝내야 합니다.","15:00에 끝나지 않은 예외 경기는 보류 상태로 보내고 운영자 알림을 만듭니다."]},{"title":"페이백 자격","body":["결제 다음 날 00:00부터 한국시간 기준 29일 동안 매일 Unranked 일반 쟁탈전 또는 복수전의 공격자로 모든 5개 답안과 필수 풀이 증거를 정상 제출해야 합니다.","공격 시작만으로는 인정하지 않고 승패는 관계없으며, 하루 여러 번 제출해도 하루 1회만 인정합니다.","페이백 점수와 공정성 검토 기준을 함께 충족해야 하며, 금액과 점수 구간은 결제할 때 안내된 기준으로 판정합니다."]}]},{"number":6,"title":"공정한 경기와 운영 검토","sections":[{"title":"자동 감지와 공개 범위","body":["공식 1대1 경기는 자동 공정성 확인 대상입니다.","악용 방지를 위해 구체적인 감지 기준과 판정 방식은 공개하지 않습니다.","검토 신호는 부정행위 확정이 아니며 최종 판정은 운영 검토 뒤 안내합니다."]},{"title":"양측 일시정지와 24시간 검토","body":["경기에서 운영 확인 신호가 감지되면 경기 종료 뒤 공격자와 방어자 모두의 신규 매치메이킹을 일시정지합니다.","운영자는 양측의 문제별 답안·풀이시간·필수 증거와 제출된 소명 자료를 원칙적으로 24시간 안에 함께 확인합니다.","검토 결과가 나오기 전까지 이 경기의 Arena 상태 변경과 공격자가 예치한 페이백 점수 정산을 보류합니다.","이용 주기의 페이백 심사 시점이 검토 중 도래하면 심사를 탈락 처리하지 않고 해당 경기의 최종 판정까지 보류합니다. 검토 시작·완료 및 최종 결과는 플랫폼 우편함과 이메일로 안내합니다."]},{"title":"추가 소명 자료","body":["운영자는 필요하면 공격자 또는 방어자에게 추가 소명 자료를 요청할 수 있습니다.","요청은 GOAT Arena 우편함과 이메일로 안내되며, 사용자는 안내된 업로드 버튼으로 실제 풀이과정 사진을 제출할 수 있습니다.","요청을 받은 사용자가 요청 시점부터 24시간 안에 응답하지 않으면 추가 소명 자료가 없는 것으로 처리하며, 기한이 끝난 뒤에는 제출할 수 없습니다.","운영자는 기한 안에 제출된 자료와 기존 답안·풀이시간·필수 풀이 증거를 함께 검토해 최종 판정합니다.","실제 풀이 흐름이 분명히 확인되는 자료를 기한 안에 제출해야 억울한 오판 가능성을 줄일 수 있습니다."]},{"title":"검토 결과 안내","body":["운영 검토 결과는 공격자와 방어자에게 GOAT Arena 우편함과 이메일로 함께 안내합니다.","안내에는 이상 없음 또는 위반 판정, 경기 정산 결과, 매치메이킹 제한 여부와 정지 시간 보상 여부가 포함됩니다.","검토가 진행되는 동안 구매한 29일 학습권 패키지의 유효성은 유지됩니다."]},{"title":"부정행위가 아닌 경우","body":["운영자가 경기 양측 모두 이상 없다고 판단하면 두 참가자의 매치메이킹 일시정지를 해제하고 해당 경기를 유효 경기로 인정합니다.","보류된 페이백 점수와 Arena 상태는 원래 1대1 경기 승패 규정에 따라 정산합니다.","각 참가자에게 매치메이킹이 정지됐던 실제 시간만큼 현재 이용 주기의 만료·페이백 심사 시각을 연장합니다. 검토가 24시간을 넘기면 초과 시간을 포함한 전체 정지 시간을 보상합니다.","따라서 페이백 심사 직전에 검토가 시작돼도 해당 기회를 잃지 않습니다. 이 보상은 페이백 점수를 직접 지급하는 방식이 아니라 동일한 매칭 가능 시간을 돌려주는 방식입니다."]},{"title":"부정행위가 확정된 경우","body":["공격자의 부정행위가 확정되면 공격자가 예치한 페이백 점수를 방어자에게 전부 이전합니다.","방어자의 부정행위가 확정되면 공격자가 예치한 페이백 점수를 공격자에게 전부 반환하고 Arena 상태는 공격자 승리 기준으로 처리합니다.","양측 모두 부정행위가 확정되면 Arena 상태는 유지하고 공격자가 예치한 페이백 점수는 전부 소각합니다.","위반이 확정된 이용자는 경기 정산 뒤 해당 이용 주기에 사용 가능한 페이백 점수의 1/3을 정수 단위로 올림해 추가 소각합니다.","부정행위가 확정된 사용자는 경고 1회, 운영 결과 통보 직후부터 5일간 매치메이킹 금지, 해당 이용 주기 페이백 심사 자동 탈락을 적용합니다.","부정행위가 확정된 참가자에게는 검토 일시정지 시간을 보상하지 않습니다. 함께 검토받았으나 위반이 확인되지 않은 상대 참가자에게는 실제 일시정지 시간을 보상합니다. 구매한 29일 학습권 패키지 자체는 유효하지만 5일 제재 기간에는 GOAT Arena 매치메이킹을 이용할 수 없습니다."]}]}],"paybackPolicy":{"displayName":"29일 학습 패키지","priceAmount":29000,"initialLearningDays":29,"initialPaybackScoreDays":29,"dailyMatchLimitsByTier":[{"tier":"BRONZE","tierLabel":"브론즈","attackLimit":3,"defenseLimit":1},{"tier":"SILVER","tierLabel":"실버","attackLimit":3,"defenseLimit":1},{"tier":"GOLD","tierLabel":"골드","attackLimit":3,"defenseLimit":2},{"tier":"PLATINUM","tierLabel":"플래티넘","attackLimit":3,"defenseLimit":2},{"tier":"EMERALD","tierLabel":"에메랄드","attackLimit":3,"defenseLimit":3},{"tier":"DIAMOND","tierLabel":"다이아몬드","attackLimit":3,"defenseLimit":3},{"tier":"MASTER","tierLabel":"마스터","attackLimit":3,"defenseLimit":4},{"tier":"GRANDMASTER","tierLabel":"그랜드마스터","attackLimit":3,"defenseLimit":4},{"tier":"CHALLENGER","tierLabel":"챌린저","attackLimit":3,"defenseLimit":4}],"minimumStreakDays":29,"minimumScoreDays":30,"bands":[{"minScoreDays":0,"maxScoreDays":29,"ratePercent":0,"expectedPaybackAmount":0},{"minScoreDays":30,"maxScoreDays":34,"ratePercent":50,"expectedPaybackAmount":14500},{"minScoreDays":35,"maxScoreDays":39,"ratePercent":80,"expectedPaybackAmount":23200},{"minScoreDays":40,"maxScoreDays":null,"ratePercent":100,"expectedPaybackAmount":29000}],"lastModifiedAt":"2026-08-01T15:00:00.000Z","effectiveFrom":"2026-08-01T15:00:00.000Z","isFallback":true},"mainPolicy":null,"upcomingPolicy":null,"problemDesign":{"division":"SUB","isRanked":false,"publicName":"Unranked","difficultyPrefix":"U","principles":["Unranked 두 사용자는 U1~U9 중 방어자 티어에 해당하는 완전히 같은 5문항을 풉니다.","U1은 기초 일반 중심으로 시작하고 U8부터 준킬러를 한 문항씩 섞어 단계적으로 적응시킵니다.","U1~U9에는 킬러를 넣지 않으며 U9도 상위 일반과 준킬러까지만 사용합니다.","각 경기의 1번에서 5번으로 갈수록 문항 난이도가 높아집니다."],"matchupRows":[{"matchup":"브론즈 방어","anchor":"브론즈","difficultyCode":"U1"},{"matchup":"실버 방어","anchor":"실버","difficultyCode":"U2"},{"matchup":"골드 방어","anchor":"골드","difficultyCode":"U3"},{"matchup":"플래티넘 방어","anchor":"플래티넘","difficultyCode":"U4"},{"matchup":