vedReferenceMeanPercent":46.1,"observedReferenceCount":215},{"order":3,"code":"D5","label":"상위 일반 상","minimumCorrectRatePercent":35,"maximumCorrectRatePercent":42,"rangeLabel":"35% 이상 42% 미만","observedReferenceMeanPercent":38.6,"observedReferenceCount":159},{"order":4,"code":"D5","label":"상위 일반 상","minimumCorrectRatePercent":35,"maximumCorrectRatePercent":42,"rangeLabel":"35% 이상 42% 미만","observedReferenceMeanPercent":38.6,"observedReferenceCount":159},{"order":5,"code":"D6","label":"준킬러 하","minimumCorrectRatePercent":25,"maximumCorrectRatePercent":35,"rangeLabel":"25% 이상 35% 미만","observedReferenceMeanPercent":30.1,"observedReferenceCount":165}],"referenceAveragePercent":39.9},{"stage":"U9","tierLabel":"챌린저","slots":[{"order":1,"code":"D4","label":"상위 일반 하","minimumCorrectRatePercent":42,"maximumCorrectRatePercent":50,"rangeLabel":"42% 이상 50% 미만","observedReferenceMeanPercent":46.1,"observedReferenceCount":215},{"order":2,"code":"D5","label":"상위 일반 상","minimumCorrectRatePercent":35,"maximumCorrectRatePercent":42,"rangeLabel":"35% 이상 42% 미만","observedReferenceMeanPercent":38.6,"observedReferenceCount":159},{"order":3,"code":"D5","label":"상위 일반 상","minimumCorrectRatePercent":35,"maximumCorrectRatePercent":42,"rangeLabel":"35% 이상 42% 미만","observedReferenceMeanPercent":38.6,"observedReferenceCount":159},{"order":4,"code":"D6","label":"준킬러 하","minimumCorrectRatePercent":25,"maximumCorrectRatePercent":35,"rangeLabel":"25% 이상 35% 미만","observedReferenceMeanPercent":30.1,"observedReferenceCount":165},{"order":5,"code":"D6","label":"준킬러 하","minimumCorrectRatePercent":25,"maximumCorrectRatePercent":35,"rangeLabel":"25% 이상 35% 미만","observedReferenceMeanPercent":30.1,"observedReferenceCount":165}],"referenceAveragePercent":36.7}],"accuracyPrinciples":["Unranked는 U1~U9 단계별로 서로 다른 문항 조합을 사용합니다.","D1~D6은 기준 정답률을 70% 이상, 60~70%, 50~60%, 42~50%, 35~42%, 25~35%로 나눈 난이도입니다.","표의 평균은 난이도를 설명하기 위한 참고값이며 개인의 정답 확률이나 경기 결과를 보장하지 않습니다."],"curveRows":[{"division":"U1~U3","sequence":"기초 일반 → 일반","example":"처음 시작해도 풀이 흐름을 익힐 수 있는 구간"},{"division":"U4~U7","sequence":"일반 → 상위 일반","example":"조건 결합과 역추론을 단계적으로 추가"},{"division":"U8~U9","sequence":"상위 일반 → 준킬러","example":"킬러 없이 준킬러 입문"}],"compositionHeadline":"Unranked는 기초 일반에서 시작해 준킬러 입문까지 올라가며 킬러는 사용하지 않습니다.","matchSpec":[["브론즈·실버·골드","기초 일반과 일반 중심"],["플래티넘·에메랄드·다이아몬드","일반과 상위 일반 중심"],["마스터·그랜드마스터·챌린저","상위 일반과 준킬러 입문"],["총점","100점 (문항당 20점)"],["제한 시간","문항당 10분"],["문제 동일성","두 사용자에게 완전히 같은 문제"],["정답 형식","3자리 이하 자연수 주관식"],["직접 출제 범위","대수, 미적분Ⅰ, 확률과 통계"],["기초 연계 범위","공통수학Ⅰ·Ⅱ의 위계·연계 개념"],["그래프·표","풀이에 필요한 그래프와 표는 문제와 함께 제공"],["난이도 코드","U1~U9 전용 조합"],["반복 방지","한 경기 안 유형 중복 금지 + 양쪽 참가자의 최근 공식 경기 5개 유형 우선 제외"]],"semiKillerDefinition":"Unranked는 D1~D6 난이도를 사용합니다.","curriculumAlignment":{"sourceTitle":"2028학년도 대학수학능력시험 예시문항 안내자료집","directCourses":["대수","미적분Ⅰ","확률과 통계"],"indirectCourses":["공통수학Ⅰ","공통수학Ⅱ"],"behaviorDomains":["계산","이해","추론","문제해결"],"representationRequirements":["식·그래프·표·그림 사이의 정보를 해석할 수 있어야 합니다.","그래프 또는 표가 문항 조건에 포함될 때 생성된 수치와 함께 경기 화면에 표시합니다."]}}},"main":{"division":"MAIN","title":"Ranked 경기 규정","eyebrow":"RANKED RULEBOOK","intro":"Ranked는 Unranked에서 페이백 자격을 달성한 사용자가 학습일수를 예치해 상향 쟁탈전·하위 티어 초대전·복수전을 진행하는 상위 경쟁 구간입니다.","summary":["두 사용자는 Ranked 전용 R1~R9 조합의 같은 주관식 5문항을 문항당 최대 10분 동안 풉니다. R4부터 준킬러, R7부터 킬러를 섞습니다.","이전 문항으로 돌아갈 수 없고, 5번 문항 완료 또는 시간 종료 뒤 문제는 닫힙니다. 새로고침·일시적 연결 끊김에도 제한시간은 계속 흐르며 같은 문항이 다시 표시됩니다.","문제가 닫힌 뒤 60초 안에 풀이 증거 사진 1~5장을 제출합니다. 이 필수 증거를 기한 안에 내지 않으면 별도 소명 기한 없이 자동 패배합니다.","매치가 성립한 뒤에는 상대의 서비스 닉네임만 표시하며 실명은 공개하지 않습니다.","승패는 점수 → 정답 수 → 정답 문항 풀이시간 → 전체 풀이시간 순으로 정합니다.","완전히 동점이면 방어자가 승리합니다.","1대1 경기 결과로 배치고사에서 정한 실력 기준은 바뀌지 않습니다. 공격자가 이기면 티어·티어 내 순위·GP가 함께 교환됩니다."],"rules":[{"number":1,"title":"진입과 학습일수","sections":[{"title":"진입 조건","body":["Unranked에서 페이백 자격이 확정되면 Ranked로 이동합니다.","Ranked 학습일수는 Unranked 이월분, Ranked 진입 보너스와 경기 이전분으로 구성됩니다."]},{"title":"통합 Ranked","body":["Ranked의 티어 순위와 공식 1대1 경기는 고등학생·N수생·대학생·직장인 구분 없이 하나의 통합 풀에서 계산합니다.","소속은 공개 랭킹의 소속 정보로만 활용하며 매칭 가능 상대나 티어 내 순위를 나누지 않습니다.","최종 종합 랭킹과 Unranked 순위도 모든 이용자를 통합해 계속 표시합니다."]},{"title":"잔액 구분","body":["사용 가능 학습일수, 초대 예약 학습일수, 경기 예치 학습일수를 분리해 중복 사용을 막습니다.","세 잔액이 모두 0이고 미정산 경기가 없으면 Ranked 이용이 만료되며, 이후 절차는 규정 8의 재구독 기준을 따릅니다."]}]},{"number":2,"title":"상향 쟁탈전과 자동 상대 선정","sections":[{"title":"목표 선택","body":["하위 티어 사용자는 목표 상위 티어만 선택합니다.","조건을 충족한 사용자 중 한 명과 자동으로 연결되며, 선정된 상위 티어 사용자는 자동 참가합니다."]},{"title":"통합 후보 선정","body":["상대는 전체 Ranked에서 목표 티어·이용 자격·최근 상대 제외 조건을 통과한 후보 중에서 찾습니다.","최근 24시간 동안 강제 방어를 가장 적게 한 사용자들을 우선 후보군으로 구성하고, 횟수가 같은 후보 안에서 무작위로 한 명을 정합니다.","공식 경기 종료 뒤 6시간 동안은 다시 강제 자동 방어자로 배정하지 않으며, 진행 중 경기나 초대 예약이 있는 사용자도 강제 방어 후보에서 제외합니다.","6시간 유예 중에도 초대전 적격 조건을 만족하면 상위 티어 사용자의 초대 알림을 받고 자발적으로 수락하거나 거절할 수 있습니다.","닉네임·특정 계정은 직접 선택할 수 없습니다."]},{"title":"자동 방어 미응시","body":["자동 배정된 방어전을 시작하지 않은 기록이 5회 누적되면 자동 방어 후보에서 제외됩니다.","자동 방어 제외 중에도 보유 학습일수는 일일 차감 규정대로 줄어들며, 잔액이 모두 소진되면 규정 8의 Ranked 만료·재구독 절차를 따릅니다.","참가 가능한 공격을 한 번 정상적으로 신청하면 미응시 누적이 0회로 초기화되고 자동 방어 배정이 다시 활성화됩니다."]},{"title":"티어 차이","body":["상향 쟁탈전의 최대 티어 차이는 3단계입니다.","차이별 최소 예치 일수는 1단계 1일, 2단계 2일, 3단계 3일이며 공통 최대 예치는 5일입니다.","1단계 차이는 1~5일, 2단계 차이는 2~5일, 3단계 차이는 3~5일을 선택할 수 있고 4단계 이상은 신청할 수 없습니다.","상향 쟁탈전은 공격자만 예치 뒤 최소 1일을 남겨야 하며, 자동 방어자는 활성 상태의 1일 이상이면 됩니다.","경기 종료 뒤 6시간 유예는 강제 자동 방어에만 적용합니다. 이 시간에도 수락형 하위 티어 초대전 알림을 받고 자발적으로 수락하거나 거절할 수 있습니다.","수락형 하위 티어 초대전은 양측이 예치 뒤 최소 1일을 남겨야 합니다."]},{"title":"시작 기한","body":["성립한 공식 매치는 양측이 24시간 안에 시작해야 하며, 일요일을 통과하면 시작 마감은 일요일 14:00입니다.","공격자만 시작하지 않으면 방어자 승리, 방어자만 시작하지 않으면 공격자 승리로 자동 정산합니다. 양측 모두 시작하지 않으면 승패 없이 취소하고 실제로 예치한 학습일수를 각각 반환합니다."]}]},{"number":3,"title":"하위 티어 초대전","sections":[{"title":"초대 생성","body":["상위 티어 사용자가 목표 하위 티어만 선택하고 학습일수를 예약합니다.","특정 사용자를 선택할 수 없으며 조건을 충족한 하위 티어 사용자에게 초대장이 전달됩니다.","초대 수락 화면에는 양측 티어와 티어 차이, 양측이 각각 예치할 학습일수, 수락자의 승리·패배 시 Arena 상태와 학습일수 결과를 먼저 표시합니다.","가장 먼저 조건을 확인하고 수락을 완료한 한 명과만 매치가 성립하며, 수락 시 양측이 같은 학습일수를 예치합니다."]},{"title":"후보 필터","body":["최근 7일 안에 공식 매치가 성립한 상대는 자동 제외합니다. 단, 직전 경기의 복수전은 이 재대결 제한의 예외입니다.","같은 사용자가 유지할 수 있는 미성립 초대는 목표 티어 하나당 1개입니다."]},{"title":"취소와 기한","body":["매치 성립 전 직접 취소는 무료이며 예약 일수를 전부 반환합니다.","초대 예약 자체에는 고정 24시간 만료가 없습니다.","일일 차감으로 초대자의 사용 가능 일수가 0이 되면 예약을 자동 취소하고 1일 수수료를 적용합니다."]}]},{"number":4,"title":"Ranked Arena 상태","sections":[{"title":"경기 결과","body":["상단 공통 규정의 판정 순서를 모든 Ranked 경기에 동일하게 적용합니다.","공격자가 이기면 티어·티어 내 순위·GP를 모두 교환하고, 방어자가 이기면 세 값 모두 유지합니다."]}]},{"number":5,"title":"Ranked 학습일수 정산","sections":[{"title":"상향 쟁탈전 정산","body":["하위 티어 공격자가 예치한 학습일수만 정산합니다. 공격자가 이기면 자기 예치금을 반환하고 Arena 상태를 교환하며, 방어자가 이기면 공격자 예치금이 방어자에게 이전됩니다.","자동 방어자는 예치하지 않으므로 상향 쟁탈전의 일반 정산은 학습일수를 새로 만들거나 소각하지 않습니다."]},{"title":"수락형 초대전 정산","body":["상위 티어의 하위 티어 초대전은 하위 사용자가 수락한 뒤 양측이 같은 학습일수를 예치합니다. 승자는 자기 예치금을 반환받고 상대 예치금을 이전받습니다.","수락 전에 예치 일수와 승패별 결과를 확인할 수 있으며, 성립한 경기에는 안내된 조건이 끝까지 적용됩니다."]},{"title":"중복 사용 방지","body":["예약 또는 예치된 학습일수는 다른 공격·초대·복수전에 다시 사용할 수 없습니다.","한 번에 하나의 미정산 공식 경기만 진행할 수 있으며, 동시에 들어온 다른 요청은 자동으로 취소됩니다."]}]},{"number":6,"title":"복수전","sections":[{"title":"신청 금액","body":["직전 경기의 패자가 결과 화면에서 즉시 신청합니다.","원경기에서 복수전 신청자가 예치했던 학습일수를 S라고 하면 복수전 신청자는 2×S일을 예치합니다.","상대는 자동 참가하며 양측 모두 24시간 안에 완료해야 합니다."]},{"title":"정상 완료","body":["Unranked 복수전과 같은 구조로 신청 금액에서 1일 수수료를 먼저 소각합니다.","공격자가 이기면 Arena 상태를 교환하고 2×S-1일을 공격자에게 반환하며 1일을 수수료로 소각합니다.","방어자가 이기면 Arena 상태를 유지하고 2×S-1일을 방어자에게 이전하며 1일을 수수료로 소각합니다."]},{"title":"24시간 미완료","body":["방어자만 미완료면 Arena 상태를 교환하고 2×S-1일을 공격자에게 반환하며 1일을 소각합니다.","공격자만 미완료면 Arena 상태를 유지하고 2×S-1일을 방어자에게 이전하며 1일을 소각합니다.","양측 모두 미완료면 Arena 상태를 유지하고 신청 금액 전부를 소각합니다.","복수전은 최근 7일 재대결 제한의 예외입니다."]}]},{"number":7,"title":"일요일 운영과 이용 종료","sections":[{"title":"일요일 마감","body":["매주 일요일 14:00부터 신규 공격·초대 수락·매치 성립·복수전 신청·준비·시작을 차단합니다.","미성립 초대 예약은 취소하지 않고 월요일 00:00까지 보류합니다.","진행 중 경기는 문항당 10분 규칙을 적용한 채 15:00까지 끝내며 예외는 보류 상태와 운영자 알림으로 전환합니다."]},{"title":"이용 종료","body":["사용 가능·예약·경기 예치 학습일수가 모두 0이고 미정산 경기가 없으면 Ranked 이용이 만료되며 규정 8의 재구독 절차로 전환됩니다.","만료 시점에 진행 중인 공식 경기가 있으면 그 경기를 먼저 끝내고 정산한 뒤 이용 종료 여부를 확정합니다.","Ranked 달성 기록과 시즌 배지는 보존됩니다."]}]},{"number":8,"title":"Ranked 만료와 재구독","sections":[{"title":"72시간 이내","body":["만료 순간 Ranked 전체 순위와 참가자 수를 기준으로 Unranked 시작 위치를 계산합니다.","72시간 안에 재구매하면 별도 시험 없이 환산된 티어·GP·Unranked 전체 순위로 시작하며, 정상 만료 기록은 최소 플래티넘을 보장합니다."]},{"title":"72시간 초과","body":["랭크 복귀전을 완료해야 합니다.","최고 배치는 정상 환산 결과보다 정확히 한 티어 아래이며, 시험 결과가 더 낮으면 그 결과를 적용합니다."]},{"title":"시즌 보상","body":["Ranked 시즌 보상은 프로필에 보존되는 성취 배지로 지급합니다.","성취 배지는 시즌이 끝나거나 Unranked로 이동해도 보존되며 학습일수로 교환되지 않습니다."]}]},{"number":9,"title":"공정한 경기와 운영 검토","sections":[{"title":"자동 감지와 공개 범위","body":["공식 1대1 경기는 자동 공정성 확인 대상입니다.","악용 방지를 위해 구체적인 감지 기준과 판정 방식은 공개하지 않습니다.","검토 신호는 부정행위 확정이 아니며 최종 판정은 운영 검토 뒤 안내합니다."]},{"title":"양측 일시정지와 24시간 검토","body":["경기에서 운영 확인 신호가 감지되면 경기 종료 뒤 공격자와 방어자 모두의 신규 매치메이킹을 일시정지합니다.","운영자는 양측의 문제별 답안·풀이시간·필수 증거와 제출된 소명 자료를 원칙적으로 24시간 안에 함께 확인합니다.","검토 결과가 나오기 전까지 이 경기의 Arena 상태 변경과 예치 학습일수 정산을 보류합니다.","검토 시작·완료 및 최종 결과는 플랫폼 우편함과 이메일로 함께 안내합니다."]},{"title":"추가 소명 자료","body":["운영자는 필요하면 공격자 또는 방어자에게 추가 소명 자료를 요청할 수 있습니다.","요청은 GOAT Arena 우편함과 이메일로 안내되며, 사용자는 안내된 업로드 버튼으로 실제 풀이과정 사진을 제출할 수 있습니다.","요청을 받은 사용자가 요청 시점부터 24시간 안에 응답하지 않으면 추가 소명 자료가 없는 것으로 처리하며, 기한이 끝난 뒤에는 제출할 수 없습니다.","운영자는 기한 안에 제출된 자료와 기존 답안·풀이시간·필수 풀이 증거를 함께 검토해 최종 판정합니다.","실제 풀이 흐름이 분명히 확인되는 자료를 기한 안에 제출해야 억울한 오판 가능성을 줄일 수 있습니다."]},{"title":"검토 결과 안내","body":["운영 검토 결과는 공격자와 방어자에게 GOAT Arena 우편함과 이메일로 함께 안내합니다.","안내에는 이상 없음 또는 위반 판정, 경기 정산 결과, 매치메이킹 제한 여부와 정지 시간 보상 여부가 포함됩니다.","검토가 진행되는 동안 보유 학습일수와 이용 권한의 유효성은 유지됩니다."]},{"title":"부정행위가 아닌 경우","body":["운영자가 경기 양측 모두 이상 없다고 판단하면 두 참가자의 매치메이킹 일시정지를 해제하고 해당 경기를 유효 경기로 인정합니다.","보류된 학습일수와 Arena 상태는 원래 1대1 경기 승패 규정에 따라 정산합니다.","각 참가자에게 매치메이킹이 정지됐던 실제 시간만큼 현재 이용 주기의 만료·평가 시각을 연장합니다. 검토가 24시간을 넘기면 초과 시간을 포함한 전체 정지 시간을 보상합니다.","이 시간 보상은 학습일수를 경기 자산으로 새로 지급하는 방식이 아니라 동일한 매칭 가능 시간을 돌려주는 방식입니다."]},{"title":"부정행위가 확정된 경우","body":["상향 쟁탈전·하위 티어 초대전·복수전 모두 실제로 예치된 학습일수만 정산합니다. 공격자가 위반하면 그 공격자가 예치한 학습일수는 방어자에게 이전하고, 방어자가 위반하면 방어자가 예치한 학습일수는 공격자에게 이전합니다. 각 참가자의 예치가 없는 경기에서는 존재하지 않는 예치금을 새로 만들지 않습니다.","상위 티어 공격이 포함된 경기에서 공격자의 위반이 확정되면 Arena 상태를 교환하고, 방어자의 위반이 확정되면 Arena 상태를 유지합니다. 그 밖의 경기에서는 위반자가 승리하지 않도록 해당 경기의 공격·방어 방향으로 Arena 상태를 처리합니다.","양측 모두 위반이 확정되면 Arena 상태는 유지하고 양측이 실제로 예치한 학습일수는 모두 소각합니다.","위반이 확정된 이용자는 경기 정산 뒤 해당 이용 주기에 사용 가능한 학습일수의 1/3을 정수 단위로 올림해 추가 소각합니다.","부정행위가 확정된 사용자는 경고 1회와 운영 결과 통보 직후부터 5일간 매치메이킹 금지를 적용합니다. Ranked 사용자는 이미 페이백을 완료한 상태이므로 페이백 심사 탈락 항목을 적용하지 않습니다.","부정행위가 확정된 참가자에게는 검토 일시정지 시간을 보상하지 않습니다. 함께 검토받았으나 위반이 확인되지 않은 상대 참가자에게는 실제 일시정지 시간을 보상합니다. 이용 권한의 유효기간은 유지되지만 5일 제재 기간에는 GOAT Arena 매치메이킹을 이용할 수 없습니다."]},{"title":"경기별 적용 규정","body":["예치 금액·티어 차이·수수료·정산 방식은 경기를 만들 때 안내된 조건으로 확정됩니다.","경기 도중 운영 규정이 바뀌어도 이미 시작된 경기의 조건은 바뀌지 않습니다."]}]}],"paybackPolicy":null,"mainPolicy":{"displayName":"기본 Ranked 정책","policyVersionCode":"MAIN-DEFAULT-20260802","maximumTargetTierGap":3,"stakeDaysByTierGap":[{"tierGap":1,"stakeDays":1},{"tierGap":2,"stakeDays":2},{"tierGap":3,"stakeDays":3}],"repeatOpponentExclusionDays":7,"revengeStakeMultiplier":2,"revengeFeeDays":1,"effectiveFrom":"2026-08-01T15:00:00.000Z","effectiveUntil":null,"lastModifiedAt":"2026-08-01T15:00:00.000Z"},"upcomingPolicy":null,"problemDesign":{"division":"MAIN","isRanked":true,"publicName":"Ranked","difficultyPrefix":"R","principles":["Ranked 두 사용자는 R1~R9 중 방어자 티어에 해당하는 완전히 같은 5문항을 풉니다.","R1~R3은 일반·상위 일반, R4부터 준킬러, R7부터 킬러를 섞어 경쟁 변별력을 높입니다.","R9은 준킬러 4문항과 정답률 8% 미만의 최상위 킬러 1문항으로 구성합니다.","각 경기의 1번에서 5번으로 갈수록 문항 난이도가 높아집니다."],"matchupRows":[{"matchup":"브론즈 방어","anchor":"브론즈","difficultyCode":"R1"},{"matchup":"실버 방어","anchor":"실버","difficultyCode":"R2"},{"matchup":"골드 방어","anchor":"골드","difficultyCode":"R3"},{"matchup":"플래티넘 방어","anchor":"플래티넘","difficultyCode":"R4"},{"matchup":"에메랄드 방어","anchor":"에메랄드","difficultyCode":"R5"},{"matchup":"다이아몬드 방어","anchor":"다이아몬드","difficultyCode":"R6"},{"matchup":"마스터 방어","anchor":"마스터","difficultyCode":"R7"},{"matchup":"그랜드마스터 방어","anchor":"그랜드마스터","difficultyCode":"R8"},{"matchup":"챌린저 방어","anchor":"챌린저","difficultyCode":"R9"}],"accuracyRows":[{"stage":"R1","tierLabel":"브론즈","slots":[{"order":1,"code":"D2","label":"일반 하","min